// Across all 7 phases you'll build ONE production-grade product:
// An AI Career Advisor — RAG over a resume + jobs corpus,
// agents that take real actions, deployed live.

{
  "product": "AI Career Advisor",
  "user_input": "I'm a Data Engineer with 4 years at Stripe.
                 Should I aim for Senior AI Eng at Anthropic?",

  "what_it_does": [
    "Parses your resume (LLM extraction)",
    "Retrieves relevant job postings (RAG over 10K jobs)",
    "Calls tools: salary lookup, fit-score, mock interview",
    "Produces a 90-day plan, evaluated for hallucination",
    "Streams the answer to a deployed web UI"
  ],

  "shipped_with": ["GPT-4o", "Claude 3.5", "pgvector",
                   "FastAPI", "Vercel", "evals + guardrails"]
}

// Phase 1: Call your first LLM
// Phase 2: Engineer the prompts that drive it
// Phase 3: Add RAG over the jobs/resumes corpus
// Phase 4: Wrap it as an agent that takes actions
// Phase 5: Build evals so it doesn't ship hallucinations
// Phase 6: Deploy + monitor it for real users
// Phase 7: Use it on your resume to land the offer

tools = [{
    "name": "salary_lookup",
    "description": "Get total comp for a role/level/location.",
    "input_schema": {
        "type": "object",
        "properties": {
            "role": {"type": "string", "enum": ["AI Engineer",
                "ML Engineer", "Data Engineer", "SWE"]},
            "level": {"type": "string", "enum": ["mid", "senior",
                "staff", "principal"]},
            "location": {"type": "string"},
        },
        "required": ["role", "level", "location"],
    },
}]

msg = client.messages.create(
    model="claude-3-5-sonnet-latest",
    max_tokens=1024,
    tools=tools,
    messages=[{
        "role": "user",
        "content": "What does Senior AI Eng at Anthropic SF pay?"
    }],
)

# Claude returns:
# tool_use → salary_lookup({
#   "role": "AI Engineer",
#   "level": "senior",
#   "location": "San Francisco"
# })
# Your code runs the tool, returns the result, model continues.

def safe_advisor(user_input: str, user_id: str) -> str:
    # 1. Rate limit
    if rate_limited(user_id): raise HTTPError(429)

    # 2. Jailbreak detection
    if is_jailbreak(user_input):
        return "I can only help with career questions."

    # 3. PII redaction BEFORE sending to LLM
    sanitized = redact_pii(user_input)
    # "my SSN is 123-45-6789" → "my SSN is [REDACTED]"

    # 4. Call the model
    raw = career_advisor(sanitized)

    # 5. Output moderation
    if openai.moderations.create(input=raw).results[0].flagged:
        log_incident(user_id, raw)
        return "Let me try that again..."

    # 6. Fact-check the output (LLM-as-judge)
    if not is_grounded(raw, sanitized):
        return regenerate_with_guardrails(sanitized)

    return raw
